{"path": "units/chain/stage1.py", "content": "import csv


def parse_orders(path):
    """Read a CSV of orders and return a list of dicts with int values.

    The file is expected to have a header row (e.g. ``id,qty,price``).
    Every field of every data row is converted to ``int``.
    """
    with open(path, newline="") as fh:
        reader = csv.DictReader(fh)
        rows = []
        for raw in reader:
            if raw is None:
                continue
            row = {key: int(value) for key, value in raw.items() if key is not None}
            if not row:
                continue
            rows.append(row)
    return rows
"}

{"path": "units/chain/stage3.py", "content": "def total_by_price(rows):
    """Sum ``qty`` grouped by ``price``."""
    totals = {}
    for row in rows:
        price = row["price"]
        totals[price] = totals.get(price, 0) + row["qty"]
    return totals
"}

{"path": "units/chain/stage4.py", "content": "def report(totals):
    """Format ``{price: total}`` as ``"price:total\\n"`` lines, price ascending."""
    return "".join("%s:%s\n" % (price, totals[price]) for price in sorted(totals))
"}
